var t=[{title:`Begin met een rustige oefenronde`,text:`Doe de beweging zonder gewicht of met het lichtste hulpmiddel dat je hebt. Voeg een klein gewicht toe voor een warming-upset en controleer of je bewegingsbereik, ademhaling en tempo stabiel blijven. Elke beweging heeft zijn eigen werkgewicht: een gewicht dat prettig voelt voor een row kan veel te zwaar zijn voor een lateral raise.`},{title:`Herhalingen in reserve`,text:`Herhalingen in reserve (RIR) is hoeveel goede herhalingen je denkt dat je nog zou kunnen doen. Voor algemene training is het een praktisch startpunt om veel sets af te sluiten met ongeveer twee of drie herhalingen over, al hoef je dat niet elke keer te halen. Voelt een geplande set van 10 alsof je er nog 10 had kunnen doen, dan kan het gewicht te licht zijn voor je doel.`},{title:`Pas aan tijdens de training`,text:`Stel dat het schema drie sets van acht tot twaalf vraagt. Eindigt je eerste set bij acht met wankele techniek en niets meer over, verlaag dan het gewicht. Zijn twaalf herhalingen vloeiend en nog redelijk makkelijk, probeer dan een kleine verhoging bij de volgende set. Rust lang genoeg om te kunnen beoordelen of het gewicht of de vermoeidheid het probleem veroorzaakte.`},{title:`Wanneer de gewichtssprongen te groot zijn`,text:`Is de volgende dumbbell te zwaar, voeg dan een herhaling, een beheerste pauze of een extra goede set toe. Is zelfs je lichtste gewicht te zwaar, gebruik dan lichaamsgewicht, een weerstandsband of een andere hefboom. Forceer nooit mislukte herhalingen om een vast aantal te halen.`},{title:`TrainUp gebruiken`,text:`Je schema geeft sets, herhalingen en rust maar geen gewichten, dus jij kiest het gewicht. Leg tijdens de training de herhalingen vast die je echt deed, en beoordeel daarna de inspanning van de training van 1 tot 10. Voel je pijn, word je duizelig of raak je steeds je techniek kwijt, stop dan of verander de oefening; voeg geen weerstand toe. “Ik voel pijn” beëindigt de huidige oefening meteen.`}];var i=[{label:`Standpunt van het ACSM uit 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Samenvatting van de krachttrainingsrichtlijn van het ACSM 2026`,url:`https://acsm.org/resistance-training-guidelines-update-2026/`},{label:`Mayo Clinic: veiligheid en techniek bij krachttraining`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`}];var a={sections:t,sources:i};export{a as default,t as sections,i as sources};